"""Traceability matrix for the eval suite: every testable documented requirement.

Pure standard library. REQUIREMENTS is the list of requirement rows; CHECKS maps
each check ID used by any row to its precise definition (the contract that the
checker modules implement). See REQUIREMENTS.md for the human-readable table.

Byte limits: MB = 1,000,000 bytes (as the docs state); MiB/GiB = 2**20 / 2**30.
"Identical" predictions means max |delta p| <= 1e-8 after row normalisation.
"""

CATEGORIES = ("contract", "causality", "scoring", "robustness", "packaging", "data-fact")
TESTABLE_BY = ("contract.py", "perturb.py", "scoring.py", "entry.py", "generator.py", "manual")


def _r(rid, source, quote, category, testable_by, check_ids, note=None):
    row = {
        "id": rid,
        "source": source,
        "quote": quote,
        "category": category,
        "testable_by": testable_by,
        "check_ids": list(check_ids),
    }
    if note:
        row["note"] = note
    return row


